using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text.Json;
using System.Collections.Concurrent;

static class Api {
 [StructLayout(LayoutKind.Sequential)] public struct CI {public int Size,Flags;public IntPtr Handle;public Native.POINT Position;}
 [DllImport("user32.dll")] public static extern bool GetCursorInfo(ref CI info);
 [DllImport("gdi32.dll",SetLastError=true)] public static extern IntPtr CreateBitmap(int w,int h,uint planes,uint bits,byte[] data);
 [DllImport("user32.dll",SetLastError=true)] public static extern IntPtr CreateIconIndirect(ref Native.ICONINFO info);
 [DllImport("user32.dll")] public static extern int GetGuiResources(IntPtr process,int flags);
 [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
 [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc cb,IntPtr state);
 public delegate bool EnumProc(IntPtr h,IntPtr state);
 public delegate void WinEventProc(IntPtr hook,uint e,IntPtr h,int obj,int child,uint thread,uint time);
 [DllImport("user32.dll")] public static extern IntPtr SetWinEventHook(uint min,uint max,IntPtr module,WinEventProc cb,uint pid,uint tid,uint flags);
 [DllImport("user32.dll")] public static extern bool UnhookWinEvent(IntPtr hook);
 [DllImport("kernel32.dll",SetLastError=true)] public static extern IntPtr CreateWaitableTimerExW(IntPtr attr,IntPtr name,uint flags,uint access);
 [DllImport("kernel32.dll",SetLastError=true)] public static extern bool SetWaitableTimer(IntPtr timer,ref long due,int period,IntPtr callback,IntPtr arg,bool resume);
 [DllImport("kernel32.dll")] public static extern uint WaitForSingleObject(IntPtr h,uint ms);
 [DllImport("kernel32.dll")] public static extern bool CloseHandle(IntPtr h);
 public static CI Cursor(){CI i=new(){Size=Marshal.SizeOf<CI>()};if(!GetCursorInfo(ref i))throw new Exception("GetCursorInfo");return i;}
 public static long Now=>Stopwatch.GetTimestamp();public static double Ms(long q)=>q*1000.0/Stopwatch.Frequency;
 public static IntPtr Solid(int size,int frame){
  byte[] color=new byte[checked(size*size*4)],mask=new byte[((size+15)/16)*2*size];var rgb=Fixtures.Colors[frame];
  for(int i=0;i<color.Length;i+=4){color[i]=(byte)rgb[2];color[i+1]=(byte)rgb[1];color[i+2]=(byte)rgb[0];color[i+3]=255;}
  var c=CreateBitmap(size,size,1,32,color);var m=CreateBitmap(size,size,1,1,mask);if(c==IntPtr.Zero||m==IntPtr.Zero){if(c!=IntPtr.Zero)Native.DeleteObject(c);if(m!=IntPtr.Zero)Native.DeleteObject(m);throw new Exception("CreateBitmap "+Marshal.GetLastWin32Error());}
  try{Native.ICONINFO i=new(){IsIcon=0,HotX=(uint)(size/2),HotY=(uint)(size/2),Color=c,Mask=m};var h=CreateIconIndirect(ref i);if(h==IntPtr.Zero)throw new Exception("CreateIconIndirect "+Marshal.GetLastWin32Error());return h;}finally{Native.DeleteObject(c);Native.DeleteObject(m);}
 }
}
sealed record HookSample(long Qpc,uint Event,uint EventTime,long Handle,int Flags);
sealed class CursorEvents : IDisposable {
 readonly Thread thread;readonly ManualResetEventSlim ready=new();readonly ConcurrentQueue<HookSample> queue=new();public readonly ConcurrentQueue<HookSample> History=new();Control? dispatch;ApplicationContext? ctx;Api.WinEventProc? callback;IntPtr hook;public int RegistrationError;
 public CursorEvents(){thread=new Thread(()=>{dispatch=new Control();_=dispatch.Handle;ctx=new ApplicationContext();callback=(a,e,h,o,c,t,tm)=>{if(o!=-9)return;try{var ci=Api.Cursor();var s=new HookSample(Api.Now,e,tm,ci.Handle.ToInt64(),ci.Flags);History.Enqueue(s);queue.Enqueue(s);}catch{}};hook=Api.SetWinEventHook(0x8002,0x800C,IntPtr.Zero,callback,0,0,0);if(hook==IntPtr.Zero)RegistrationError=Marshal.GetLastWin32Error();ready.Set();Application.Run(ctx);if(hook!=IntPtr.Zero)Api.UnhookWinEvent(hook);dispatch.Dispose();});thread.IsBackground=true;thread.SetApartmentState(ApartmentState.STA);thread.Start();ready.Wait();if(hook==IntPtr.Zero)throw new Exception("WinEvent registration failed "+RegistrationError);}
 public bool Next(out HookSample? s)=>queue.TryDequeue(out s);
 public void Clear(){while(queue.TryDequeue(out _)){} }
 public void Dispose(){if(dispatch!=null)dispatch.BeginInvoke(()=>ctx!.ExitThread());thread.Join(2000);ready.Dispose();}
}
sealed class PreciseWait : IDisposable {
 readonly IntPtr timer=Api.CreateWaitableTimerExW(IntPtr.Zero,IntPtr.Zero,2,0x1F0003);
 public PreciseWait(){if(timer==IntPtr.Zero)throw new Exception("High-resolution timer unavailable");}
 public void Until(long qpc){double ms=Api.Ms(qpc-Api.Now);if(ms<=0)return;long due=-(long)(ms*10000);if(due==0)return;if(!Api.SetWaitableTimer(timer,ref due,0,IntPtr.Zero,IntPtr.Zero,false))throw new Exception("SetWaitableTimer");Api.WaitForSingleObject(timer,5000);}
 public void Dispose()=>Api.CloseHandle(timer);
}
sealed record Backup(uint Role,string Hash,int Width,int Height,int HotX,int HotY);
sealed record HostCommand(int Serial,uint Role,bool Private);
sealed record HostAck(int Serial,uint Role,bool Private,long Handle,int Pid,long Qpc);
sealed record PublishSample(long Qpc,long End,uint Role,int Frame,int Size,bool Ok,int Error);
static class Program {
 static readonly JsonSerializerOptions Json=new(){WriteIndented=true,IncludeFields=true};
 static string root="";static readonly uint[] Roles={32516,32651};static readonly Dictionary<uint,Backup> backups=new();static readonly List<object> cases=new();static readonly List<PublishSample> published=new();static readonly List<object> restored=new();static Process? host,watch;static IntPtr hostWindow;static DesktopPointerCapture? capture;static CursorEvents? hooks;static PreciseWait? wait;static int serial;static long activeHandle;static uint activeRole;static long phaseOrigin;static int scale=96,lastFrame=-1;static readonly Dictionary<long,uint> roleByHandle=new();static readonly List<object> transitions=new();static bool pumping;
 static string Flag(uint role)=>Path.Combine(root,$"restore-{role}.required");
 static Process Spawn(string exe,params string[] args){var p=new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true};foreach(var a in args)p.ArgumentList.Add(a);return Process.Start(p)??throw new Exception("Spawn");}
 static IntPtr Shared(uint r)=>Native.LoadCursorW(IntPtr.Zero,new IntPtr(r));
 [STAThread] static int Main(string[] args){try{if(args[0]=="--restore")return RestoreWatch(args);if(args[0]=="--capture")return CaptureOnly(args[1]);root=Path.GetFullPath(args[0]);if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new Exception("Use an empty artifact directory");Directory.CreateDirectory(root);Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);return Run(args.Length<2?"functional":args[1]);}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static void BackupAll(){foreach(var r in Roles){var h=Shared(r);if(h==IntPtr.Zero)throw new Exception("Shared role unavailable");var d=Native.Dimensions(h);var hash=Native.PixelHash(h);string p=Path.Combine(root,$"baseline-{r}.cur");File.WriteAllBytes(p,Native.SaveStaticCursor(h));var v=Native.Load(p,0);try{if(Native.PixelHash(v)!=hash||Native.Dimensions(v)!=d)throw new Exception("Backup roundtrip");}finally{Native.DestroyCursor(v);}backups.Add(r,new(r,hash,d.W,d.H,d.X,d.Y));roleByHandle[h.ToInt64()]=r;}File.WriteAllText(Path.Combine(root,"backups.json"),JsonSerializer.Serialize(backups.Values,Json));watch=Spawn(Environment.ProcessPath!,"--restore",Environment.ProcessId.ToString(),root);}
 static int RestoreWatch(string[] a){root=a[2];int pid=int.Parse(a[1]);var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<240000){try{if(Process.GetProcessById(pid).HasExited)break;}catch{break;}Thread.Sleep(100);}var results=new List<object>();foreach(var b in JsonSerializer.Deserialize<Backup[]>(File.ReadAllText(Path.Combine(root,"backups.json")))!){if(!File.Exists(Flag(b.Role)))continue;try{var h=Native.Load(Path.Combine(root,$"baseline-{b.Role}.cur"),0);bool ok=Native.SetSystemCursor(h,b.Role);bool match=ok&&Native.PixelHash(Shared(b.Role))==b.Hash;if(match)File.Delete(Flag(b.Role));results.Add(new{b.Role,ok,match});}catch(Exception e){results.Add(new{b.Role,Error=e.ToString()});}}File.WriteAllText(Path.Combine(root,"watchdog.json"),JsonSerializer.Serialize(results,Json));return Directory.GetFiles(root,"restore-*.required").Length==0?0:2;}
 static void Restore(uint r){if(!File.Exists(Flag(r)))return;var b=backups[r];var h=Native.Load(Path.Combine(root,$"baseline-{r}.cur"),0);bool ok=Native.SetSystemCursor(h,r);var d=Native.Dimensions(Shared(r));bool match=ok&&Native.PixelHash(Shared(r))==b.Hash&&d==(b.Width,b.Height,b.HotX,b.HotY);restored.Add(new{Role=r,ok,match});if(!match)throw new Exception("Restore "+r);File.Delete(Flag(r));}
 static PublishSample Publish(uint role,int frame,int size,IntPtr prepared=default,bool log=true){if(!backups.ContainsKey(role))throw new Exception("Missing backup");if(!File.Exists(Flag(role)))File.WriteAllText(Flag(role),"");var h=prepared==IntPtr.Zero?Api.Solid(size,frame):Native.CopyImage(prepared,2,0,0,0);if(h==IntPtr.Zero)throw new Exception("CopyImage");long q=Api.Now;bool ok=Native.SetSystemCursor(h,role);var s=new PublishSample(q,Api.Now,role,frame,size,ok,ok?0:Marshal.GetLastWin32Error());if(log)published.Add(s);if(!ok)throw new Exception("SetSystemCursor "+s.Error);return s;}
 static HostAck Select(uint role,bool priv=false){File.Delete(Path.Combine(root,"host-frozen"));int n=++serial;File.WriteAllText(Path.Combine(root,"command.tmp"),JsonSerializer.Serialize(new HostCommand(n,role,priv)));File.Move(Path.Combine(root,"command.tmp"),Path.Combine(root,"command.json"),true);var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<3000){if(pumping)Pump();try{var a=JsonSerializer.Deserialize<HostAck>(File.ReadAllText(Path.Combine(root,"ack.json")));if(a?.Serial==n){File.WriteAllText(Path.Combine(root,"host-frozen"),"");return a;}}catch{}Thread.Sleep(1);}throw new Exception("Host select timeout");}
 static void Sleep(int ms){var start=Api.Now;while(Api.Ms(Api.Now-start)<ms){if(pumping)Pump();Thread.Sleep(1);}if(capture?.Failure!=null)throw capture.Failure;}
 static void Pump(){while(hooks!.Next(out var ev)){if(ev==null)continue;if(roleByHandle.TryGetValue(ev.Handle,out var role)&&ev.Flags!=0){if(ev.Handle==activeHandle)continue;uint old=activeRole;activeHandle=ev.Handle;activeRole=role;phaseOrigin=ev.Qpc;lastFrame=0;transitions.Add(new{Qpc=ev.Qpc,Role=role,PreviousRole=old,Scale=scale,Source="WinEvent",ev.Event});Publish(role,0,scale);if(old!=0&&old!=role)Publish(old,0,scale);}else{activeHandle=ev.Handle;activeRole=0;lastFrame=-1;}}
  if(activeRole!=0){double t=Api.Ms(Api.Now-phaseOrigin)%2400;int f=t<300?0:t<800?1:t<1500?2:3;if(f!=lastFrame){lastFrame=f;Publish(activeRole,f,scale);}}
 }
 static void RoleChanges(){Publish(32516,0,scale);Publish(32651,0,scale);hooks!.Clear();var initial=Api.Cursor();activeHandle=initial.Handle.ToInt64();activeRole=roleByHandle.GetValueOrDefault(activeHandle);phaseOrigin=Api.Now;lastFrame=0;transitions.Add(new{Qpc=phaseOrigin,Role=activeRole,PreviousRole=0u,Scale=scale,Source="initial snapshot",Event=0u});pumping=true;var selections=new List<object>();foreach(var r in new uint[]{32516,32651,32516,32516,32651,32516}){var a=Select(r);Sleep(r==32516?370:840);selections.Add(new{a.Role,a.Qpc,ObservedActive=activeRole,Scale=scale,LastFrame=lastFrame,Handle=Api.Cursor().Handle.ToInt64()});}pumping=false;cases.Add(new{Name="role-events-and-reentry",Selections=selections,Transitions=transitions.ToArray(),ExpectedTransitions=5,ObservedTransitions=transitions.Count,Scale=scale});}
 static object ScreenColorCoverage(int frame,int size){var ci=Api.Cursor();var b=Screen.PrimaryScreen!.Bounds;using var bmp=new Bitmap(b.Width,b.Height);using(var g=Graphics.FromImage(bmp))g.CopyFromScreen(b.X,b.Y,0,0,b.Size);var rgb=Fixtures.Colors[frame];int expected=0,matches=0;int left=ci.Position.X-size/2,top=ci.Position.Y-size/2;for(int y=8;y<b.Height;y+=32)for(int x=8;x<b.Width;x+=32){if(x>=left&&x<left+size&&y>=top&&y<top+size){expected++;var c=bmp.GetPixel(x,y);if(c.R==rgb[0]&&c.G==rgb[1]&&c.B==rgb[2])matches++;}}return new{ExpectedSamplePoints=expected,MatchingSoftwarePixels=matches};}
 static void HugeSizes(){Select(32516);capture!.AuditDesktop=true;foreach(int size in new[]{128,256,257,384,512,1024,2048,4096}){try{var before=Api.Cursor();long q=Api.Now;var op=Publish(32516,2,size);Sleep(100);Native.GetCursorPos(out var diagPosition);Native.SetCursorPos(diagPosition.X+1,diagPosition.Y);Sleep(100);var shape=capture!.Samples.FirstOrDefault(s=>s.Qpc>=q&&s.Frame==2&&s.Width==size);var d=Native.Dimensions(Shared(32516));var after=Api.Cursor();var software=capture.Audits.Where(a=>a.Qpc>=q).LastOrDefault();cases.Add(new{Name="huge-size",Requested=size,CreatedWidth=d.W,CreatedHeight=d.H,HotX=d.X,HotY=d.Y,PresentedPointerShape=shape!=null,ObservedWidth=shape?.Width,ObservedHeight=shape?.Height,LatencyMs=shape==null?(double?)null:Api.Ms(shape.Qpc-op.Qpc),PositionUnchanged=before.Position.X==after.Position.X&&before.Position.Y==after.Position.Y,SoftwareCoverage=software,Status="Observed"});}catch(Exception e){cases.Add(new{Name="huge-size",Requested=size,Status="Failed",Error=e.ToString()});Restore(32516);}}
 }
 static object Stats(Process p){p.Refresh();return new{Pid=p.Id,CpuMs=p.TotalProcessorTime.TotalMilliseconds,WorkingSet=p.WorkingSet64,PrivateBytes=p.PrivateMemorySize64,Handles=p.HandleCount,User=Api.GetGuiResources(p.Handle,1),Gdi=Api.GetGuiResources(p.Handle,0)};}
 static void Bench(string name,int size,int hz,int seconds,bool cache){Select(32516);var p=Process.GetCurrentProcess();IntPtr[] prepared=cache?Enumerable.Range(0,4).Select(f=>Api.Solid(size,f)).ToArray():Array.Empty<IntPtr>();try{ // warm up only outside measurement
  if(hz>0)for(int n=0;n<12;n++)Publish(32516,n%4,size,cache?prepared[n%4]:IntPtr.Zero,false);
  GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();var before=Stats(p);long q=Api.Now;double cpu=p.TotalProcessorTime.TotalMilliseconds;int calls=0;var times=new List<double>();var lateness=new List<double>();var resources=new List<object>();long duration=(long)(seconds*(double)Stopwatch.Frequency);int perSecond=0;
  if(hz==0){Thread.Sleep(seconds*1000);}else{while(Api.Now-q<duration){long due=q+(long)(calls*(double)Stopwatch.Frequency/hz);wait!.Until(due);lateness.Add(Api.Ms(Api.Now-due));var start=Api.Now;Publish(32516,calls%4,size,cache?prepared[calls%4]:IntPtr.Zero,false);times.Add(Api.Ms(Api.Now-start));calls++;if(calls/hz>perSecond){perSecond=calls/hz;resources.Add(Stats(p));}}}
  double wall=Api.Ms(Api.Now-q);p.Refresh();double used=p.TotalProcessorTime.TotalMilliseconds-cpu;times.Sort();lateness.Sort();cases.Add(new{Name="consumption",Mode=name,Size=size,Hz=hz,Cached=cache,DurationMs=wall,Calls=calls,CpuMs=used,CpuPercentOneCore=100*used/wall,CpuPercentMachine=100*used/wall/Environment.ProcessorCount,LogicalProcessors=Environment.ProcessorCount,MeanWorkMs=times.Count==0?0:times.Average(),P95WorkMs=times.Count==0?0:times[(int)((times.Count-1)*0.95)],MaxWorkMs=times.Count==0?0:times[^1],P95ScheduleLatenessMs=lateness.Count==0?0:lateness[(int)((lateness.Count-1)*0.95)],MaxScheduleLatenessMs=lateness.Count==0?0:lateness[^1],Before=before,After=Stats(p),ResourceSamples=resources});
 }finally{foreach(var h in prepared)Native.DestroyCursor(h);Restore(32516);}}
 static int CaptureOnly(string path){try{using var c=new DesktopPointerCapture();c.Start();while(!File.Exists(Path.Combine(path,"capture-stop"))){Thread.Sleep(50);if(c.Failure!=null)throw c.Failure;}File.WriteAllText(Path.Combine(path,"separate-capture.json"),JsonSerializer.Serialize(new{Samples=c.Samples.ToArray()},Json));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(path,"capture-error.txt"),ex.ToString());return 2;}}
 static int Run(string mode){Native.GetCursorPos(out var originalPosition);var foreground=Native.GetForegroundWindow();int exit=1;string? failure=null;var utility=Process.GetProcessesByName("ShakeToFindCursor-x64").Select(p=>p.Id).ToArray();var self=Process.GetCurrentProcess();object? before=null,after=null;Process? observer=null;try{BackupAll();wait=new PreciseWait();string hostExe=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../NativeRoleProbe/bin/Debug/net10.0-windows/NativeRoleProbe.exe"));host=Spawn(hostExe,"--host",root);var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<4000){Api.EnumWindows((h,p)=>{Api.GetWindowThreadProcessId(h,out var pid);if(pid==host.Id)hostWindow=h;return true;},IntPtr.Zero);if(hostWindow!=IntPtr.Zero)break;Thread.Sleep(20);}if(hostWindow==IntPtr.Zero)throw new Exception("Host window unavailable");Native.SetForegroundWindow(hostWindow);Native.SetCursorPos(440,320);Select(32516);Sleep(150);
  if(mode=="functional"){capture=new DesktopPointerCapture();capture.Start();hooks=new CursorEvents();RoleChanges();HugeSizes();}
  else if(mode=="bench"){ // Capture runs in a separate process so its CPU is not charged to publisher.
   observer=Spawn(Environment.ProcessPath!,"--capture",root);Sleep(300);before=Stats(observer);
   Bench("idle-static",128,0,4,true);Bench("animated-cached",128,8,6,true);foreach(int size in new[]{128,256,512,1024,2048})Bench("60Hz-cached",size,60,6,true);Bench("60Hz-create-on-demand",512,60,5,false);
   after=observer.HasExited?new{Exited=true,ExitCode=observer.ExitCode,Error=File.Exists(Path.Combine(root,"capture-error.txt"))?File.ReadAllText(Path.Combine(root,"capture-error.txt")):"No managed error recorded"}:Stats(observer);File.WriteAllText(Path.Combine(root,"capture-stop"),"");observer.WaitForExit(3000);
  }else throw new Exception("Unknown test mode");exit=0;
 }catch(Exception e){failure=e.ToString();}finally{pumping=false;hooks?.Dispose();foreach(uint role in backups.Keys){try{Restore(role);}catch(Exception e){failure+="\nRESTORE: "+e;exit=2;}}File.WriteAllText(Path.Combine(root,"host-stop"),"");if(host!=null&&!host.HasExited)host.WaitForExit(2000);File.WriteAllText(Path.Combine(root,"capture-stop"),"");if(observer!=null&&!observer.HasExited)observer.WaitForExit(3000);Native.SetForegroundWindow(foreground);Native.SetCursorPos(originalPosition.X,originalPosition.Y);capture?.Dispose();wait?.Dispose();var report=new{Experiment="Role transitions, large native cursor sizes and publisher consumption; not product",Mode=mode,Date=DateTimeOffset.Now,OS=Environment.OSVersion.VersionString,PublisherPid=Environment.ProcessId,HostPid=host?.Id,LogicalProcessors=Environment.ProcessorCount,QpcFrequency=Stopwatch.Frequency,Failure=failure,ExitCode=exit,UtilityPids=utility,OriginalUtilityStillRunning=utility.All(id=>{try{return !Process.GetProcessById(id).HasExited;}catch{return false;}}),Backups=backups.Values,Restores=restored,PendingRestoreFlags=Directory.GetFiles(root,"restore-*.required").Select(Path.GetFileName),Cases=cases,Publications=published,Events=hooks?.History.ToArray(),Samples=capture?.Samples.ToArray(),DesktopAudits=capture?.Audits.ToArray(),ObserverBefore=before,ObserverAfter=after};File.WriteAllText(Path.Combine(root,"report.json"),JsonSerializer.Serialize(report,Json));Console.WriteLine(JsonSerializer.Serialize(new{exit,failure,Mode=mode,Cases=cases},Json));}return exit;}
}
